import{z as i,x as B,o as t,c as p,q as s,j as A,D as E,d as r,s as l,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"动态完备与复制","description":"","frontmatter":{"title":"动态完备与复制","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/dynamic-completeness.md","filePath":"econ/dynamic-completeness.md","lastUpdated":1791413859000}'),d={name:"econ/dynamic-completeness.md"};function m(c,a,D,h,u,f){const n=B("Mermaid");return t(),p("div",null,[a[2]||(a[2]=s('<h1 id="动态完备与复制" tabindex="-1">动态完备与复制 <a class="header-anchor" href="#动态完备与复制" aria-label="Permalink to &quot;动态完备与复制&quot;">​</a></h1><div class="epigraph"><p>状态可以很多，证券可以很少：只要能沿信息到达再交易，动态策略可以张成静态菜单张不成的支付。</p><footer>—— Kreps, Multiperiod Securities and the Efficient Allocation of Risk, 1982；对照 Harrison–Pliska 的布朗完全性</footer></div><p><a href="/econ/equivalent-martingale-measure">上一课</a>写明：完全当且仅当 EMM 唯一。本课缺口是<strong>完全从何而来</strong>——不是一开始就列出 \\(S\\) 张 Arrow 证券，而是动态再交易。不重写 \\(\\mathbb{Q}\\) 的定义，不把复制写成限价簿上的对冲执行。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态一期，\\(J\\lt S\\) 则不完全，见 <a href="/econ/incomplete-markets-gei">GEI</a>。多期：信息是树（或域流 \\(\\mathcal{F}_t\\)）。每期可按当时价格调整持仓，终端支付是策略的积分。Kreps（1982）强调：动态完备指策略空间张成所有（平方可积、适应的）或有支付，不是指某期现货市场列全。Black–Scholes 的世界只有股票与债券两种证券，连续交易加布朗信息，却能复制欧式期权——因为信息由一个布朗生成，两种连续交易的资产恰好对准那个不确定性来源。</p><p>缺口是把「张成」从矩阵的列换成策略的随机积分。FTAP 第二定理现在有了内容：EMM 唯一 ⇔ 动态张成足够。</p><p><span class="marginnote">离散树：每个节点的分叉数不得超过当时可交易的独立风险资产数（加债券），否则局部不满秩。连续时间把这句话换成「风险源的个数 = 连续交易的风险资产个数」。</span></p><p><span class="marginnote">数字实例：两期、末端 4 个状态。静态完备要 4 张不同的 Arrow 证券；动态地看，第 1 期只分 2 个节点、每个节点下再分 2 枝，只要每个节点上都有股票加债券可重新交易，2 只证券就能复制全部 4 种支付——时间替你省了 2 张证券。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>复制：找可积策略 \\(\\phi\\)，使终端 \\(x=x_0+\\int\\phi\\,\\mathrm{d}S\\) 且贴现财富为 \\(\\mathbb{Q}\\)–鞅（无注入）。完全则每个 \\(x\\) 有复制，价格是复制的初始成本，也等于 \\(\\mathrm{E}^{\\mathbb{Q}}[x/B]\\)。不完全则只有 \\(\\mathrm{span}\\) 里的 \\(x\\) 有唯一价格；其余只有超复制的上界与次复制的下界——连续时间课序的定价界再写。</p><p>与状态价格课对照：静态完全是 \\(S\\) 张 Arrow；动态完全是「信息有多宽、能交易多少次、有多少独立价格过程」。Radner 式逐期开市场，可以把不完全的静态菜单做完备——前提是每期分叉被当时证券覆盖。</p>',11)),(t(),A(o,null,{default:E(()=>[l(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20STAT%5B%22%E9%9D%99%E6%80%81%3A%20%E5%88%97%E6%95%B0%20vs%20%E7%8A%B6%E6%80%81%E6%95%B0%22%5D%20--%3E%20GEI%5B%22GEI%20%E4%B8%8D%E5%AE%8C%E5%85%A8%22%5D%0A%20%20DYN%5B%22%E5%8A%A8%E6%80%81%3A%20%E7%AD%96%E7%95%A5%E7%A7%AF%E5%88%86%22%5D%20--%3E%20SPAN%5B%22%E5%BC%A0%E6%88%90%E9%80%82%E5%BA%94%E6%94%AF%E4%BB%98%22%5D%0A%20%20SPAN%20--%3E%20UNIQ%5B%22EMM%20%E5%94%AF%E4%B8%80%22%5D%0A%20%20BR%5B%22%E4%B8%80%E4%B8%AA%E5%B8%83%E6%9C%97%20%2B%20%E8%BF%9E%E7%BB%AD%E4%BA%A4%E6%98%93%22%5D%20--%3E%20BS%5B%22%E8%82%A1%E7%A5%A8%E5%80%BA%E5%88%B8%E5%8D%B3%E5%8F%AF%E5%A4%8D%E5%88%B6%E6%9C%9F%E6%9D%83%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"不要把「连续交易」写成「没有买卖价差所以能复制」。连续是域流与路径的理想化；价差会破坏精确复制，那是 Constantinides 后课，不是本课把 FTAP 收回去。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"机制是信息到达时重新配置。今天分不清的两个状态，明天若被分开，只要那时还有能区分它们的相对价格，就可以把财富挪到正确的枝上。静态菜单必须预先为每一枝准备一张证券；动态菜单用时间换证券数目。布朗之所以「一个噪声源」，是因为无穷小增量只有一个方向；再多一个独立布朗，就要再多一个连续交易的资产，否则不完全。",-1)),a[6]||(a[6]=e("p",null,"「少量证券如何靠时间覆盖更多状态」——两期树的动态复制：",-1)),(t(),A(o,null,{default:E(()=>[l(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20N0%5B%22t0%3A%20%E5%B8%82%E5%9C%BA%E5%8F%AA%E6%9C%89%E8%82%A1%E7%A5%A8%E4%B8%8E%E5%80%BA%E5%88%B8%202%20%E5%8F%AA%22%5D%20--%3E%20U%5B%22t1%20%E8%8A%82%E7%82%B9%3A%20%E4%B8%8A%22%5D%0A%20%20N0%20--%3E%20D%5B%22t1%20%E8%8A%82%E7%82%B9%3A%20%E4%B8%8B%22%5D%0A%20%20U%20--%3E%20UU%5B%22t2%3A%20%E4%B8%8A%E4%B8%8A%22%5D%0A%20%20U%20--%3E%20UD%5B%22t2%3A%20%E4%B8%8A%E4%B8%8B%22%5D%0A%20%20D%20--%3E%20DU%5B%22t2%3A%20%E4%B8%8B%E4%B8%8A%22%5D%0A%20%20D%20--%3E%20DD%5B%22t2%3A%20%E4%B8%8B%E4%B8%8B%22%5D%0A%20%20REB%5B%22%E5%9C%A8%E6%AF%8F%E4%B8%AA%20t1%20%E8%8A%82%E7%82%B9%E6%8C%89%E6%96%B0%E4%BF%A1%E6%81%AF%E8%B0%83%E4%BB%93%22%5D%20--%3E%20OK%5B%224%20%E7%A7%8D%E7%BB%88%E7%AB%AF%E6%94%AF%E4%BB%98%E8%A2%AB%202%20%E5%8F%AA%E8%AF%81%E5%88%B8%E5%A4%8D%E5%88%B6%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<p><span class="marginnote">类比做汤调味：静态完备要求一次备齐所有调料；动态完备像分阶段加盐——中途尝一口（信息到达），再补一勺（调仓）。只要阶段够多、每阶段手里有可用的料，少量手段也能拼出很多种最终口味。</span></p><p>Kyle 的连续拍卖是信息泄漏过程，不是复制过程。不要把知情者的战略强度当成动态完备——完备是菜单与域流的关系，与是否有人知情无关。有私人信息时，对谁而言的域流可以不同，复制对做市端与对知情者不是同一策略。那是接口，本课用公共域流。</p><p><span class="marginnote">跳跃过程每个跳的幅度若是新方向，可能需要无穷多证券才能完全。 Merton 跳扩散的期权一般不能用股票债券精确复制——不完全，价格落在区间或靠均衡定 \\(m\\)。</span></p><p><span class="marginnote">常见误区：以为『证券少于状态数』就注定不完全。缺不缺列，取决于信息如何到达与能否中途重交易：一个布朗驱动、连续可调仓，2 只资产就够；跳跃带来全新方向的风险时，再多资产也可能真的缺一列。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证明随机积分的表示定理。后文 Merton 组合会在完全市场里当策略存在；CIR、Black–Scholes 作为均衡会给出具体的完全经济。也不要把动态完备写成「现实能连续对冲」——执行是量化栏。</p><p>下一课回到 Harrison–Kreps：他们如何把鞅定价从套利推到跨期信念，并允许异质预期下的投机。本课只钉张成。</p><p>后课默认：动态再交易可以完备静态上看起来缺列的市场；EMM 唯一与可复制是同一件事。价差与跳跃会破坏精确复制。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>动态完备是策略张成适应支付，不是静态 Arrow 证券列全。</li><li>风险源个数对齐连续交易的风险资产个数时，少量证券即可完全。</li><li>复制价格 = EMM 期望；不完全则区间。</li><li>出处：Kreps, 1982；Harrison and Pliska, 1981；对照 Black–Scholes。</li></ul>',10))])}const b=i(d,[["render",m]]);export{S as __pageData,b as default};
